import { existsSync, readFileSync, rmSync, statSync } from "node:fs";
import { join } from "node:path";
import { resolveLinkTargetId } from "./adapters.ts";
import { atomicWriteDurable } from "./paths.ts";
import type { AgentId, OwnershipStateV2, PlannedOp } from "./types.ts";

/**
 * Machine instructions (ADR 0002): an optional `<configBase>/agent-hub/AGENTS.md` appended to the
 * hub's `AGENTS.md` in a generated rules file in the state directory. Every rules link points at
 * that file while the machine file holds anything but whitespace, and at the hub's otherwise.
 *
 * The generated file is derived output, not an owned target: it is written atomically and is not
 * journaled, because a run interrupted at any point converges on the next one.
 */
export type MachineRulesPlan = {
  /** What rules links should point at in this run. */
  rulesSrc: string;
  machineFile: string;
  generatedPath: string;
  /** Write or keep the generated file; applied before any link. */
  writeOp: PlannedOp | null;
  /** Remove a generated file no longer wanted; applied after every link. */
  removeOp: PlannedOp | null;
  content: string | null;
};

export function machineInstructionsPath(configBase: string): string {
  return join(configBase, "agent-hub", "AGENTS.md");
}

export function generatedRulesContent(hubRules: string, hubText: string, machineFile: string, machineText: string): string {
  const nl = (s: string) => (s.endsWith("\n") ? s : `${s}\n`);
  const notice = `<!-- Generated by sync-agents from ${hubRules} and ${machineFile}. Edit those files, not this one: the next sync overwrites it. -->\n`;
  return `${notice}\n${nl(hubText)}\n${nl(machineText)}`;
}

function readIfFile(path: string): string | null {
  if (!existsSync(path)) return null;
  if (!statSync(path).isFile()) throw new Error(`machine instructions ${path} is not a regular file`);
  return readFileSync(path, "utf8");
}

export function planMachineRules(
  canonicalHubPath: string,
  homeDir: string,
  configBase: string,
  generatedPath: string,
  state: OwnershipStateV2,
  activeTargets: ReadonlySet<AgentId> | undefined,
): MachineRulesPlan {
  const hubRules = join(canonicalHubPath, "AGENTS.md");
  const machineFile = machineInstructionsPath(configBase);
  const hubText = existsSync(hubRules) && statSync(hubRules).isFile() ? readFileSync(hubRules, "utf8") : null;
  const machineText = readIfFile(machineFile);
  const active = hubText !== null && machineText !== null && machineText.trim() !== "";

  if (active) {
    const content = generatedRulesContent(hubRules, hubText, machineFile, machineText);
    const current = existsSync(generatedPath) ? readFileSync(generatedPath, "utf8") : null;
    const same = current === content;
    return {
      rulesSrc: generatedPath,
      machineFile,
      generatedPath,
      content,
      removeOp: null,
      writeOp: {
        domain: "rules",
        action: same ? "keep" : "rules-generate",
        status: same ? "ok" : "change",
        destination: generatedPath,
        observed: current === null ? "absent" : same ? "generated rules are current" : "generated rules are stale",
        intended: `${hubRules} followed by ${machineFile}`,
        ownershipBasis: "generated",
        reason: `machine instructions in ${machineFile} extend ${hubRules}${same ? "" : current === null ? "; writing the generated rules" : "; regenerating"}`,
        targetMutation: !same,
        ledgerMutation: false,
      },
    };
  }

  let removeOp: PlannedOp | null = null;
  if (existsSync(generatedPath)) {
    // A rules link this run will not re-point (an excluded target's) keeps the file alive.
    const heldBy = Object.entries(state.links)
      .filter(([, rec]) => rec.kind === "rules" && rec.target === generatedPath)
      .map(([dst]) => dst)
      .filter((dst) => {
        if (!activeTargets) return false;
        const owner = resolveLinkTargetId(dst, homeDir, configBase);
        return owner === null || !activeTargets.has(owner);
      });
    if (heldBy.length === 0) {
      removeOp = {
        domain: "rules",
        action: "rules-remove",
        status: "change",
        destination: generatedPath,
        observed: "generated rules present",
        intended: "absent",
        ownershipBasis: "generated",
        reason: `no machine instructions in ${machineFile}; rules links point at ${hubRules} again`,
        targetMutation: true,
        ledgerMutation: false,
      };
    }
  }
  return { rulesSrc: hubRules, machineFile, generatedPath, content: null, writeOp: null, removeOp };
}

export function applyMachineRulesWrite(plan: MachineRulesPlan): void {
  if (plan.content === null) throw new Error("no generated rules to write");
  atomicWriteDurable(plan.generatedPath, plan.content, 0o644);
}

export function applyMachineRulesRemove(plan: MachineRulesPlan): void {
  rmSync(plan.generatedPath, { force: true });
}
